suppressPackageStartupMessages({library(data.table);library(ggplot2)})
p='output/followup_analysis/';savep=function(x,n,w=11,h=6){for(e in c('png','pdf'))ggsave(paste0(p,'figures/',n,'.',e),x,width=w,height=h,dpi=220)}
f=fread(paste0(p,'tables/eligible_introns.tsv.gz'));meta=fread(paste0(p,'tables/downsampling_depths.tsv'));profiles=list();tests=list();zones=list()
for(s in 1:8){sid=meta$sample_id[s];message('Shape normalization ',sid);x=fread(paste0('data/results_round2/',sid,'/feature_bin_counts.tsv.gz'));x=x[variant=='all__genome_full' & kind=='intron'];x=merge(x,f[,.(feature_id,quartile,length_nt)],by='feature_id');x[,density:=aligned_bases/bin_length_nt];x[,shape:=density/sum(density),by=feature_id];x[,zone:=ifelse(bin_index<10,'first10',ifelse(bin_index>=90,'last10','middle80'))];
 z=x[,.(mass=sum(shape)),by=.(feature_id,quartile,zone)];wide=dcast(z,feature_id+quartile~zone,value.var='mass',fill=0);wide[,`:=`(first_density=first10/.1,middle_density=middle80/.8,last_density=last10/.1)];wide[,sample_id:=sid];zones[[s]]=wide
 for(q in 0:4){y=if(q==0)x else x[quartile==q];zz=if(q==0)wide else wide[quartile==q];nn=uniqueN(y$feature_id);z=y[,.(equal_intron_fraction=sum(shape)/nn,read_weighted_bases=sum(aligned_bases)),by=bin_index];z=merge(data.table(bin_index=0:99),z,all.x=TRUE);z[is.na(equal_intron_fraction),`:=`(equal_intron_fraction=0,read_weighted_bases=0)];z[,read_weighted_fraction:=read_weighted_bases/sum(read_weighted_bases)];z[,`:=`(sample_id=sid,construct=meta$construct[s],assay=meta$assay[s],replicate=meta$biological_replicate[s],quartile=q,supported_introns=nn,eligible_introns=if(q==0)nrow(f) else sum(f$quartile==q))];profiles[[paste(s,q)]]=z
 for(b in c('first','last')){v=zz[[paste0(b,'_density')]]-zz$middle_density;tt=suppressWarnings(wilcox.test(v,mu=0,exact=FALSE));tests[[paste(s,q,b)]]=data.table(sample_id=sid,quartile=q,boundary=b,supported_introns=nrow(zz),median_paired_density_difference=median(v),fraction_boundary_greater=mean(v>0),wilcoxon_p=tt$p.value)}}
}
pr=rbindlist(profiles);te=rbindlist(tests);te[,q_BH:=p.adjust(wilcoxon_p,'BH')];fwrite(pr,paste0(p,'tables/metaintron_equal_shape_profiles.tsv'),sep='\t');fwrite(te,paste0(p,'tables/metaintron_read_boundary_tests.tsv'),sep='\t');fwrite(rbindlist(zones),paste0(p,'tables/metaintron_per_intron_zone_weights.tsv.gz'),sep='\t')
savep(ggplot(pr,aes(bin_index+.5,equal_intron_fraction,color=factor(construct),linetype=replicate))+geom_line()+facet_grid(assay~quartile)+theme_bw()+labs(x='Intron position (%)',y='Mean within-intron read-density fraction per1% bin',title='Each supported intron contributes one total weight',subtitle='0=all lengths;1-4=length quartiles; zero-support introns reported separately'),'metaintron_equal_shape',14,7)
savep(ggplot(pr[quartile==0],aes(bin_index+.5,read_weighted_fraction,color=factor(construct),linetype=replicate))+geom_line()+facet_wrap(~assay)+theme_bw()+labs(x='Intron position (%)',y='Fraction of aligned bases per1% bin',title='Read-weighted metaintron sensitivity'),'metaintron_read_weighted')
sp=fread(paste0(p,'tables/summit_normalized_positions.tsv.gz'));sp[,zone:=ifelse(fraction<.1,'first10',ifelse(fraction>=.9,'last10','middle80'))];st=sp[,.(n=.N),by=.(kind,quartile,zone)];den=sp[,.(total=.N),by=.(kind,quartile)];st=merge(st,den,by=c('kind','quartile'));st[,expected_fraction:=ifelse(zone=='middle80',.8,.1)];st[,observed_fraction:=n/total];st[,enrichment:=observed_fraction/expected_fraction];st[,binomial_p:=mapply(function(k,n,p)binom.test(k,n,p)$p.value,n,total,expected_fraction)];st[,q_BH:=p.adjust(binomial_p,'BH')];fwrite(st,paste0(p,'tables/summit_boundary_length_tests.tsv'),sep='\t')
savep(ggplot(sp[kind=='3UTR'],aes(fraction*100))+geom_histogram(binwidth=1,boundary=0,fill='#226778')+theme_bw()+labs(x="3'UTR position (%)",y='Assigned summit count',title="MSI2 reference: normalized 3'UTR summit histogram"),'UTR_summit_histogram')
savep(ggplot(sp[kind=='3UTR'],aes(fraction*100))+stat_ecdf(color='#226778')+geom_abline(intercept=0,slope=.01,lty=2)+theme_bw()+labs(x="3'UTR position (%)",y='Cumulative fraction of summits'),'UTR_summit_ECDF')
w=fread(paste0(p,'tables/spatial_components_and_delta_iterations.tsv.gz'));w[,`:=`(ratio324=ifelse(`324_SMI`>0,`324_CLIP`/`324_SMI`,NA_real_),ratio328=ifelse(`328_SMI`>0,`328_CLIP`/`328_SMI`,NA_real_))];v=melt(w,id.vars=c('profile','bin','position','iteration'),measure.vars=c('ratio324','ratio328'));q=v[iteration>0,.(median=median(value,na.rm=TRUE),low=quantile(value,.025,na.rm=TRUE),high=quantile(value,.975,na.rm=TRUE),finite_draws=sum(is.finite(value))),by=.(profile,bin,position,variable)];fwrite(q,paste0(p,'tables/spatial_ratio_summary.tsv'),sep='\t');savep(ggplot(q[profile%in%c('donor_into_intron','acceptor_into_intron')],aes(position,median,color=variable,fill=variable))+geom_ribbon(aes(ymin=low,ymax=high),alpha=.15,color=NA)+geom_line()+geom_hline(yintercept=1,lty=2)+facet_wrap(~profile)+theme_bw()+labs(x='Distance into intron (nt)',y='Mean CLIP CPM depth / mean SMI CPM depth',title='Inward intron CLIP/SMI ratios; 50 resamples',subtitle='No pseudocount; undefined when SMI depth=0'),'intron_inward_ratio')
